3	/// The volume line's model (road map "audio" AP8a, spec §11 AU-80…AU-84): the
4	/// dB scale it is drawn on, the plan's envelope per clip, what a press on it
5	/// edits, the ops a point is made of, and the drag's session. The drawing and
6	/// the gesture's wiring are `TimelineView+VolumeLine.swift`.
7	///
8	/// **The line is a view of actions** (AU-80): a point is an action's END
9	/// (`end.audio.volume`), a drag writes `set_audio {volume}` or that end, and
10	/// nothing is persisted that actions do not already persist.
11	
12	/// The line's dB scale (AU-81): +30.103 dB (`AudioNormalize.maxGain`, ×32) at
13	/// the top of `rect`, −60 dB at its bottom. A gain at or under 0.001 draws at
14	/// the bottom, one above 32 (a track's volume can carry the plan there,
15	/// AU-103) at the top. `rect` is the line's rect inset 1 pt top and bottom,
16	/// in the timeline content view's flipped space (its top is `minY`).
17	struct VolumeScale: Equatable {
18	    static let topDB: Double = 20 * log10(AudioNormalize.maxGain)
19	    static let floorDB: Double = -60
20	    let rect: CGRect
21	
22	    /// The y of `gain` (linear).
23	    func y(gain: Double) -> CGFloat {
24	        let db = gain > 0.001 ? 20 * log10(gain) : Self.floorDB
25	        let clamped = min(max(db, Self.floorDB), Self.topDB)
26	        let fraction = (Self.topDB - clamped) / (Self.topDB - Self.floorDB)
27	        return rect.minY + CGFloat(fraction) * rect.height
28	    }
29	
30	    /// The dB a pointer travel of `deltaY` (press y minus pointer y, so
31	    /// positive is UP) spans on this scale.
32	    func decibels(deltaY: CGFloat) -> Double {
33	        guard rect.height > 0 else { return 0 }
34	        return Double(deltaY / rect.height) * (Self.topDB - Self.floorDB)
35	    }
36	}
