38	/// One handle's plan, read for the line (AU-81): clip id → the ramps of the
39	/// plan audio track holding that clip's audio segment, cut to the segment.
40	/// Decoded lazily, at most once, as `DuckCurves` is (`DuckSpeech.swift`), so
41	/// a refresh that draws no line never pays for the plan.
42	final class VolumeLines {
43	    /// The handle the lines were read from — the timeline's own
44	    /// (`ProjectDocument.editedProject`), which a point's evaluated volume is
45	    /// read from too.
46	    let project: ReelProject
47	    private var byClip: [UInt32: [PlanRamp]]?
48	
49	    init(_ project: ReelProject) {
50	        self.project = project
51	    }
52	
53	    /// The clip's envelope in the handle's time, or nil when the plan has no
54	    /// audio segment for it.
55	    func ramps(for clip: UInt32) -> [PlanRamp]? {
56	        if byClip == nil { byClip = Self.read(project.plan) }
57	        return byClip?[clip]
58	    }
59	
60	    private static func read(_ plan: CompositionPlan?) -> [UInt32: [PlanRamp]] {
61	        var found: [UInt32: [PlanRamp]] = [:]
62	        for track in plan?.audioTracks ?? [] {
63	            let ramps = track.ramps ?? []
64	            var spans: [UInt32: (start: Ticks, end: Ticks)] = [:]
65	            for segment in track.segments where segment.duration > 0 {
66	                let end = segment.start + segment.duration
67	                if let span = spans[segment.clip] {
68	                    spans[segment.clip] = (min(span.start, segment.start), max(span.end, end))
69	                } else {
70	                    spans[segment.clip] = (segment.start, end)
71	                }
72	            }
73	            for (clip, span) in spans where found[clip] == nil {
74	                found[clip] = cut(ramps, from: span.start, to: span.end)
75	            }
76	        }
77	        return found
78	    }
79	
80	    /// `ramps` cut to `[from, to)`, each leg interpolated where it is cut.
81	    static func cut(_ ramps: [PlanRamp], from: Ticks, to: Ticks) -> [PlanRamp] {
82	        ramps.compactMap { ramp in
83	            let end = ramp.start + ramp.duration
84	            let start = max(ramp.start, from)
85	            let stop = min(end, to)
86	            guard stop > start else { return nil }
87	            func value(_ t: Ticks) -> Double {
88	                guard ramp.duration > 0 else { return ramp.to }
89	                let f = Double(t - ramp.start) / Double(ramp.duration)
90	                return ramp.from + (ramp.to - ramp.from) * f
91	            }
92	            return PlanRamp(start: start, duration: stop - start, from: value(start), to: value(stop))
93	        }
94	    }
95	
96	    /// The gain the ramps give at `t`, or nil where none covers it. A ramp's
97	    /// end belongs to the next one; the last one's end is its own.
98	    static func gain(at t: Ticks, in ramps: [PlanRamp]) -> Double? {
99	        for ramp in ramps where ramp.start <= t && t < ramp.start + ramp.duration {
100	            let f = Double(t - ramp.start) / Double(max(ramp.duration, 1))
101	            return ramp.from + (ramp.to - ramp.from) * f
102	        }
103	        if let last = ramps.last, t == last.start + last.duration { return last.to }
104	        return nil
105	    }
106	}
