117	/// What a drag on the line edits (AU-82): the clip's base volume, or an
118	/// action's end; each with the value it starts from.
119	enum VolumeLineTarget: Equatable {
120	    case base(volume: Double)
121	    case end(action: UInt32, volume: Double)
122	
123	    var volume: Double {
124	        switch self {
125	        case .base(let volume), .end(_, let volume): return volume
126	        }
127	    }
128	}
129	
130	enum VolumeLine {
131	    /// AU-82: inside an action naming `end.audio.volume` → that action; else
132	    /// the latest action ENDED at or before `clipTime` naming it; else the base.
133	    static func target(of clip: ClipSnapshot, at clipTime: Ticks) -> VolumeLineTarget {
134	        let naming = clip.actions.filter { $0.end.audio?.volume != nil }
135	        if let inside = naming.first(where: { $0.start <= clipTime && clipTime < $0.endTime }),
136	           let volume = inside.end.audio?.volume {
137	            return .end(action: inside.id, volume: volume)
138	        }
139	        if let held = naming.filter({ $0.endTime <= clipTime }).max(by: { $0.endTime < $1.endTime }),
140	           let volume = held.end.audio?.volume {
141	            return .end(action: held.id, volume: volume)
142	        }
143	        return .base(volume: clip.audioProps.volume)
144	    }
145	
146	    /// AU-83: the ops BEFORE the dragged end, the action whose end is
147	    /// dragged and the value it starts at; nil where a point cannot go (the
148	    /// caller beeps). `clipTime` is snapped to the frame here.
149	    static func point(
150	        on clip: ClipSnapshot, at clipTime: Ticks, project: ReelProject, nextId: UInt32, fps: Fps
151	    ) -> (prefix: [ReelOp], action: UInt32, volume: Double)? {
152	        let frame = max(fps.frameDuration, 1)
153	        let t = ReelTime.snapToFrame(clipTime, fps: fps)
154	        guard t >= 0, t < clip.duration,
155	              let volume = (project.clipState(clip.id, at: clip.start + t)?["audio"]
156	                  as? [String: Any])?["volume"] as? Double
157	        else { return nil }
158	        if let inside = clip.actions.first(where: { $0.start <= t && t < $0.endTime }) {
159	            // An action a trim left running past the clip's end: `add_action`
160	            // would refuse its second half (`action_past_end`), silently.
161	            guard let end = inside.end.audio?.volume, namesOnlyVolume(inside.end),
162	                  t - inside.start >= frame, inside.endTime <= clip.duration
163	            else { return nil }
164	            var prefix: [ReelOp] = [
165	                .setAction(clip: clip.id, action: inside.id, duration: t - inside.start),
166	                .addAction(clip: clip.id, at: t, duration: inside.endTime - t),
167	                .setActionEnd(
168	                    clip: clip.id, action: nextId,
169	                    patch: ActionPatch(audio: AudioPatch(volume: end))),
170	            ]
171	            if inside.curve != .linear {
172	                prefix.append(.setAction(clip: clip.id, action: nextId, curve: inside.curve))
173	            }
174	            return (prefix, inside.id, volume)
175	        }
176	        let prevEnd = clip.actions.map(\.endTime).filter { $0 <= t }.max() ?? 0
177	        guard t - prevEnd >= frame else { return nil }
178	        return ([.addAction(clip: clip.id, at: prevEnd, duration: t - prevEnd)], nextId, volume)
179	    }
180	
181	    /// An end patch whose only key is `audio.volume`.
182	    static func namesOnlyVolume(_ end: ActionPatch) -> Bool {
183	        guard let volume = end.audio?.volume else { return false }
184	        return end.video == nil && end.text == nil && end.graphic == nil && end.speed == nil
185	            && end.audio == AudioPatch(volume: volume)
186	    }
187	
188	    /// AU-82: 0 at the bottom; else `start` (at least 0.001, so a silent
189	    /// value can be raised) moved by `decibels`, held to `check_audio`'s
190	    /// 0…32. `atBottom` is the caller's "pointer below the press and at the
191	    /// scale's `maxY − 1` or lower".
192	    static func volume(from start: Double, decibels: Double, atBottom: Bool) -> Double {
193	        if atBottom { return 0 }
194	        return min(max(max(start, 0.001) * pow(10, decibels / 20), 0), AudioNormalize.maxGain)
195	    }
196	
197	    /// The drag's readout: "+2.5 dB", one decimal, "−∞ dB" at 0.
198	    static func readout(_ volume: Double) -> String {
199	        guard volume > 0 else { return "\u{2212}\u{221E} dB" }
200	        let db = 20 * log10(volume)
201	        let text = String(format: "%.1f", abs(db))
202	        if text == "0.0" { return "0.0 dB" }
203	        return (db < 0 ? "\u{2212}" : "+") + text + " dB"
204	    }
205	}
