207	/// One drag on the line (AU-82, AU-83): the ops each tick sends are the
208	/// point's `prefix` (empty for a plain drag) and the write of `volume` to the
209	/// target.
210	struct VolumeLineSession {
211	    let clip: UInt32
212	    let target: VolumeLineTarget
213	    let prefix: [ReelOp]
214	    let pressY: CGFloat
215	    let scale: VolumeScale
216	    var volume: Double
217	    /// The pointer, for the readout.
218	    var point: CGPoint
219	
220	    var ops: [ReelOp] {
221	        switch target {
222	        case .base:
223	            return prefix + [.setAudio(clips: [clip], patch: AudioPatch(volume: volume))]
224	        case .end(let action, _):
225	            return prefix + [.setActionEnd(
226	                clip: clip, action: action, patch: ActionPatch(audio: AudioPatch(volume: volume)))]
227	        }
228	    }
229	
230	    var undoName: String { prefix.isEmpty ? "Set Volume" : "Add Volume Point" }
231	
232	    mutating func update(y: CGFloat) {
233	        volume = VolumeLine.volume(
234	            from: target.volume, decibels: scale.decibels(deltaY: pressY - y),
235	            atBottom: y > pressY && y >= scale.rect.maxY - 1)
236	    }
237	}
