239	extension TimelineHit {
240	    /// AU-84: a press on the line with ⇧ held (toggle membership, ⌥⇧ slip)
241	    /// or a double-click (rename) is the clip's own; anything else unchanged.
242	    func resolvingVolumeLine(flags: NSEvent.ModifierFlags, clicks: Int) -> TimelineHit {
243	        guard case .volumeLine(let clip, _) = self,
244	              flags.contains(.shift) || clicks == 2
245	        else { return self }
246	        return .clip(clip)
247	    }
248	}
