1	//! The audio group's two evaluation rules beside `actions.rs`'s `merge` and
2	//! `lerp` (road map "audio" AP8b, spec §11 AU-86): the group as JSON with
3	//! `isolation` present even at 0, and the five numbers that are switches.
4	//!
5	//! `isolation` is written only when not 0 in the file (format 31), so
6	//! `to_json` leaves a clip with none without the key — and `lerp` walks only
7	//! its FROM side's keys, so an action toward 0.8 would hold 0 for its whole
8	//! span and jump at the end. [`audio_json`] writes it, as `color_json` writes
9	//! tone's neutral keys.
10	//!
11	//! The EQ's two slopes (12 or 24 dB/octave), the hum's mains (50 or 60 Hz)
12	//! and its harmonics are integers in the schema, so `lerp_number` would
13	//! round them through every value between — a 12 → 24 slope passing 18,
14	//! which no stage designs, and a 50 → 60 mains passing 55. They are choices,
15	//! not quantities: [`hold_audio_steps`] holds each at its start value until
16	//! the action's end, which is §5.4's rule for a switch.
17	//!
18	//! The leveller's `response` is a quantity, but each response names its own
19	//! gain curve, made ahead of time from the clip's loudness (AU-66): a
20	//! response between two curves has none, so it switches at the end too.
21	
22	use serde_json::Value;
23	
24	use crate::actions::to_json;
25	use crate::model::AudioProps;
26	
27	/// A clip's audio group as JSON with `isolation` present at 0 (AU-86).
28	pub(crate) fn audio_json(audio: &AudioProps) -> Value {
29	    let mut value = to_json(audio);
30	    if let Value::Object(fields) = &mut value {
31	        if !fields.contains_key("isolation") {
32	            fields.insert("isolation".to_string(), to_json(&audio.isolation));
33	        }
34	    }
35	    value
36	}
37	
38	/// The audio numbers that switch at an action's end rather than glide
39	/// (AU-86), as JSON pointers into the evaluated state.
40	pub(crate) const HELD_AUDIO_NUMBERS: [&str; 5] = [
41	    "/audio/eq/high_pass/slope",
42	    "/audio/eq/low_pass/slope",
43	    "/audio/hum/frequency",
44	    "/audio/hum/harmonics",
45	    "/audio/leveller/response",
46	];
47	
48	/// Puts each [`HELD_AUDIO_NUMBERS`] field of `lerped` back to its value in
49	/// `from`, the state the spanning action started from. Only where both have
50	/// it: a slot present on one side alone already holds or switches whole
51	/// through `lerp`'s mismatched-type rule.
52	pub(crate) fn hold_audio_steps(from: &Value, lerped: &mut Value) {
53	    for pointer in HELD_AUDIO_NUMBERS {
54	        let Some(start) = from.pointer(pointer) else {
55	            continue;
56	        };
57	        if let Some(slot) = lerped.pointer_mut(pointer) {
58	            *slot = start.clone();
59	        }
60	    }
61	}
